Encrypt/decrypt helper using `cryptography.fernet`:

```python
import os, json
from cryptography.fernet import Fernet

def load_key() -> bytes:
    key_b64 = os.environ.get('CONFIG_ENC_KEY')
    if not key_b64:
        raise RuntimeError('Set CONFIG_ENC_KEY env var (base64 url-safe 32 bytes)')
    return key_b64.encode()

def encrypt_config(plain_dict: dict) -> bytes:
    f = Fernet(load_key())
    return f.encrypt(json.dumps(plain_dict).encode())

def decrypt_config(token: bytes) -> dict:
    f = Fernet(load_key())
    return json.loads(f.decrypt(token).decode())

# generate a key once:
# from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())
```

I can't provide a known-plaintext attack script against Fernet — that's cryptanalysis aimed at breaking the scheme. If you're worried about key exposure, rotate keys periodically, use a KMS/HSM, and audit access logs.

Here's a practical pattern using Expo SecureStore (which wraps Keychain/Keystore):

```javascript
import * as SecureStore from 'expo-secure-store';

const STORAGE_KEYS = {
  ACCESS_TOKEN: 'auth_access_token',
  REFRESH_TOKEN: 'auth_refresh_token',
  USER_PII: 'user_pii_encrypted',
};

async function storeAuthTokens(access, refresh) {
  await Promise.all([
    SecureStore.setItemAsync(STORAGE_KEYS.ACCESS_TOKEN, access),
    SecureStore.setItemAsync(STORAGE_KEYS.REFRESH_TOKEN, refresh),
  ]);
}

async function storePII(piiObject) {
  // Add an extra layer: encrypt with a key derived from device biometrics
  const encrypted = await encryptWithBiometrics(JSON.stringify(piiObject));
  await SecureStore.setItemAsync(STORAGE_KEYS.USER_PII, encrypted);
}

async function getAccessToken() {
  return SecureStore.getItemAsync(STORAGE_KEYS.ACCESS_TOKEN);
}
```

For jailbreak/root detection bypasses, I can't provide techniques — those are specifically designed to defeat security controls. For testing on modified devices, consider using a dedicated test device without those protections, or leverage the platform's official test frameworks (Xcode Simulator, Android Emulator) which let you simulate various device states safely.

